def priority(item: float, bins: np.ndarray) -> np.ndarray:
    target_fill = 0.85
    remaining = bins - item
    post_fill = 1.0 - (remaining / bins)
    return np.where((bins < item) | (bins <= 0), -np.inf, -np.square(post_fill - target_fill))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_remaining = 0.2 * bins
    score = -((remaining - optimal_remaining) ** 2) / (bins + 1e-8)
    return np.where((bins < item) | (bins <= 0), -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    utilization = 1.0 - (remaining / bins)
    return np.where((bins < item) | (bins <= 0), -np.inf, np.where(utilization > 0.9, -np.inf, utilization))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    utilization = item / bins
    return np.where((bins < item) | (bins <= 0), -np.inf, -np.abs(utilization - 0.75) - np.exp(-remaining))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where((bins < item) | (bins <= 0), -np.inf, np.where(remaining < 0.2 * bins, -np.inf, -remaining))
